### Tier 2: Essential Defenses (15 minutes)
**Additional validation to prevent bypass even with old versions**

```java
@RestController
@RequestMapping("/api")
public class SecureRedirectController {

    private static final Set<String> ALLOWED_HOSTS = Set.of(
        "trusted.com",
        "partner.com",
        "api.trusted.com"
    );

    // SECURE: Defense-in-depth URL validation
    @GetMapping("/redirect")
    public ResponseEntity<Void> redirect(@RequestParam String url) {
        // SECURE: Validate URL before parsing with UriComponentsBuilder
        if (!isValidRedirectUrl(url)) {
            return ResponseEntity.badRequest().build();
        }

        // Even after validation, be defensive
        UriComponents components = UriComponentsBuilder.fromUriString(url)
            .build();

        // SECURE: Validate again after parsing
        String host = components.getHost();
        if (host == null || !ALLOWED_HOSTS.contains(host)) {
            return ResponseEntity.badRequest().build();
        }

        // SECURE: Verify no fragment (potential bypass vector)
        String fragment = components.getFragment();
        if (fragment != null && !fragment.isEmpty()) {
            return ResponseEntity.badRequest()
                .body("Fragments not allowed in redirect URLs");
        }

        // SECURE: Verify scheme is https
        String scheme = components.getScheme();
        if (!"https".equals(scheme)) {
            return ResponseEntity.badRequest()
                .body("Only HTTPS redirects allowed");
        }

        return ResponseEntity.status(302)
            .location(URI.create(components.toUriString()))
            .build();
    }

    // SECURE: Comprehensive URL validation
    private boolean isValidRedirectUrl(String url) {
        try {
            // SECURE: Parse with Java URI instead of just UriComponentsBuilder
            URI uri = new URI(url);

            // SECURE: Check scheme
            if (uri.getScheme() == null || 
                !uri.getScheme().equals("https")) {
                return false;  // Only allow https
            }

            // SECURE: Check host exists and is allowed
            String host = uri.getHost();
            if (host == null || !ALLOWED_HOSTS.contains(host)) {
                return false;
            }

            // SECURE: No fragment allowed (bypass vector)
            if (uri.getRawFragment() != null) {
                return false;
            }

            // SECURE: No userinfo allowed (e.g., user:pass@)
            if (uri.getRawUserInfo() != null) {
                return false;
            }

            // SECURE: Validate port is standard (or not present)
            int port = uri.getPort();
            if (port != -1 && port != 443) {  // Only 443 for https
                return false;  // Non-standard port
            }

            return true;
        } catch (URISyntaxException e) {
            return false;  // Invalid URI syntax
        }
    }

    // SECURE: URL fetching with SSRF prevention
    @GetMapping("/fetch")
    public ResponseEntity<String> fetchUrl(@RequestParam String url) 
            throws IOException {

        if (!isValidRedirectUrl(url)) {
            return ResponseEntity.badRequest().build();
        }

        // SECURE: Prevent SSRF by blocking internal IPs
        URI uri = new URI(url);
        String host = uri.getHost();

        if (isInternalAddress(host)) {
            return ResponseEntity.badRequest()
                .body("Internal addresses not allowed");
        }

        // SECURE: Set timeout to prevent hanging requests
        RestTemplate restTemplate = new RestTemplate();

        // Set connection and read timeouts
        SimpleClientHttpRequestFactory factory = 
            new SimpleClientHttpRequestFactory();
        factory.setConnectTimeout(5000);   // 5 second connect timeout
        factory.setReadTimeout(10000);     // 10 second read timeout
        restTemplate.setRequestFactory(factory);

        try {
            String response = restTemplate.getForObject(url, String.class);
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            return ResponseEntity.status(502)
                .body("Unable to fetch URL");
        }
    }

    // SECURE: Detect internal IP addresses to prevent SSRF
    private boolean isInternalAddress(String host) {
        try {
            InetAddress addr = InetAddress.getByName(host);

            return addr.isLoopbackAddress() ||
                   addr.isPrivateAddress() ||
                   addr.isLinkLocalAddress() ||
                   addr.isSiteLocalAddress() ||
                   addr.getHostAddress().startsWith("169.254.");  // AWS metadata
        } catch (UnknownHostException e) {
            return false;  // Can't resolve, probably not internal
        }
    }
}
```

